#include <FreeRTOS.h>
#include <task.h>
#include <queue.h>
#include <stdio.h>

QueueHandle_t data_queue;

void EXTI0_IRQHandler(void) {
    int data = 42;
    xQueueSend(data_queue, &data, portMAX_DELAY);
}

void vTaskConsumer(void *pvParameters) {
    int received;
    while (1) {
        xQueueReceive(data_queue, &received, portMAX_DELAY);
        printf("Received: %d\n", received);
    }
}

int main(void) {
    data_queue = xQueueCreate(10, sizeof(int));
    xTaskCreate(vTaskConsumer, "Consumer", 256, NULL, 1, NULL);
    vTaskStartScheduler();
    return 0;
}
